for(const voices of Object.values(PLAYER_VOICES))Object.freeze(voices);
Object.freeze(PLAYER_VOICES);
export function resolveDialogueFrame(frame,characterId='wang'){
 const voices=frame?.voiceKey&&PLAYER_VOICES[frame.voiceKey];
 if(!voices||!Object.hasOwn(voices,characterId))return {...frame};
 return {...frame,speaker:DIALOGUE_NAMES[characterId],copy:voices[characterId]};
}
